package main

import (
	"fmt"
	"sort"
	"strings"
	"unicode"
)

// Python: Pydantic v2 models. Field names are snake_case with the schema's
// JSON name as alias; documents are read with model_validate and written
// with model_dump(mode="json", by_alias=True, exclude_unset=True), so absent
// optional fields stay absent.

func pythonHeader(source string) string {
	return "# <auto-generated>\n" +
		"#   Generated by tools/codegen from " + source + ". DO NOT EDIT.\n" +
		"#   Regenerate with: go -C tools/codegen run . -repo ../.. (from the repository root).\n" +
		"# </auto-generated>\n"
}

// pythonReserved are names a Pydantic field must not use: Python keywords
// and BaseModel attributes.
var pythonReserved = map[string]bool{
	"from": true, "import": true, "class": true, "def": true, "global": true, "in": true,
	"is": true, "lambda": true, "not": true, "or": true, "and": true, "pass": true,
	"return": true, "with": true, "yield": true, "async": true, "await": true, "type": false,
	"schema": true, "json": true, "dict": true, "copy": true, "validate": true,
	"construct": true, "fields": true,
}

func snake(s string) string {
	var b strings.Builder
	runes := []rune(s)
	for i, r := range runes {
		if unicode.IsUpper(r) {
			if i > 0 && (unicode.IsLower(runes[i-1]) || (i+1 < len(runes) && unicode.IsLower(runes[i+1]))) {
				b.WriteByte('_')
			}
			b.WriteRune(unicode.ToLower(r))
		} else if r == '-' {
			b.WriteByte('_')
		} else {
			b.WriteRune(r)
		}
	}
	name := b.String()
	if pythonReserved[name] {
		name += "_"
	}
	return name
}

func (m *Model) pyType(t TypeRef) string {
	var s string
	switch t.Kind {
	case KString:
		s = "str"
	case KInt:
		s = "int"
	case KFloat:
		s = "float"
	case KBool:
		s = "bool"
	case KJSON:
		return "Any"
	case KObject:
		s = m.names[t.Class]
	case KList:
		s = "list[" + m.pyType(*t.Elem) + "]"
	}
	if t.Nullable {
		s += " | None"
	}
	return s
}

func pyDoc(indent, doc string) string {
	if doc == "" {
		return ""
	}
	lines := wrap(strings.ReplaceAll(doc, `"""`, `'''`), 84)
	if len(lines) == 1 {
		return indent + `"""` + lines[0] + `"""` + "\n"
	}
	var b strings.Builder
	b.WriteString(indent + `"""` + lines[0] + "\n")
	for _, l := range lines[1:] {
		b.WriteString(indent + l + "\n")
	}
	b.WriteString(indent + `"""` + "\n")
	return b.String()
}

func (m *Model) emitPython(codes []ErrorCode) (map[string]string, error) {
	classes := make([]*Class, 0, len(m.order))
	for _, key := range m.order {
		classes = append(classes, m.classes[key])
	}
	sort.SliceStable(classes, func(i, j int) bool { return classes[i].Name < classes[j].Name })

	var b strings.Builder
	b.WriteString(pythonHeader("specs/*.schema.json"))
	b.WriteString(`"""Typed documents of the RtoGtoR specification (Pydantic v2 models)."""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, ConfigDict
from pydantic import Field as _Field  # the schemas define a class named Field


class _Model(BaseModel):
    # strict: values are never coerced (no "1" -> 1); frozen: use model_copy(update=...).
    model_config = ConfigDict(populate_by_name=True, extra="ignore", frozen=True, strict=True)
`)
	var names []string
	for _, c := range classes {
		names = append(names, c.Name)
		b.WriteString("\n\nclass " + c.Name + "(_Model):\n")
		if d := pyDoc("    ", c.Doc); d != "" {
			b.WriteString(d)
			if len(c.Fields) > 0 {
				b.WriteString("\n")
			}
		}
		if len(c.Fields) == 0 {
			b.WriteString("    pass\n")
		}
		for _, f := range c.Fields {
			typ := m.pyType(f.Type)
			name := snake(f.JSONName)
			if f.Required {
				fmt.Fprintf(&b, "    %s: %s = _Field(alias=%q)\n", name, typ, f.JSONName)
			} else {
				if typ != "Any" && !strings.HasSuffix(typ, "| None") {
					typ += " | None"
				}
				fmt.Fprintf(&b, "    %s: %s = _Field(default=None, alias=%q)\n", name, typ, f.JSONName)
			}
			if d := pyDoc("    ", f.Doc); d != "" {
				b.WriteString(d)
			}
		}
	}
	b.WriteString("\n\n__all__ = [\n")
	for _, n := range names {
		fmt.Fprintf(&b, "    %q,\n", n)
	}
	b.WriteString("]\n\nfor _model in list(globals().values()):\n")
	b.WriteString("    if isinstance(_model, type) and issubclass(_model, _Model):\n")
	b.WriteString("        _model.model_rebuild()\n")

	var e strings.Builder
	e.WriteString(pythonHeader("specs/error-codes.json"))
	e.WriteString(`"""Stable RtoGtoR error codes (specs/error-codes.json)."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Final, Literal

Severity = Literal["info", "warning", "error", "fatal"]


@dataclass(frozen=True)
class ErrorCodeInfo:
    """Definition of one stable error code."""

    code: str
    title: str
    severity: Severity
    retryable: bool
    meaning: str
    remediation: str


class ErrorCode:
    """Error code constants, for example ` + "`ErrorCode.MAP_005 == \"RTG-MAP-005\"`" + `."""

`)
	for _, c := range codes {
		parts := strings.Split(c.Code, "-")
		fmt.Fprintf(&e, "    %s_%s: Final = %q\n", parts[1], parts[2], c.Code)
		fmt.Fprintf(&e, "    \"\"\"%s.\"\"\"\n", strings.ReplaceAll(c.Title, `"`, `'`))
	}
	e.WriteString("\n\nERROR_CODES: Final[dict[str, ErrorCodeInfo]] = {\n")
	for _, c := range codes {
		fmt.Fprintf(&e, "    %q: ErrorCodeInfo(%q, %q, %q, %s, %q, %q),\n", c.Code, c.Code, c.Title, c.Severity,
			map[bool]string{true: "True", false: "False"}[c.Retryable], c.Meaning, c.Remediation)
	}
	e.WriteString("}\n")

	return map[string]string{
		"__init__.py":    pythonHeader("tools/codegen") + "\"\"\"Code generated from the specification.\"\"\"\n",
		"models.py":      b.String(),
		"error_codes.py": e.String(),
	}, nil
}
